'use strict';

const ConnectionHandler = require('../connections/connection-handler');
const { command_contexts } = require('../commands/command-contexts');
const { eventBus } = require('../events/event-bus').get();

// Game Handler class
class Game extends ConnectionHandler {
  /**
   * @param {import("../connections/connection")} connection
   * @param {import("../models/player").Player} player
   */
  constructor(connection, player) {
    super(connection);
    this.player = player;
    this.handlePlayerInput = command_contexts;
  }

  enter() {
    eventBus.emit('player.enteredRealm', { player: this.player });
  }

  /**
   * @param {string} input
   */
  handle(input) {
    this.handlePlayerInput(this.player, input);
  }

  leave() {
    eventBus.emit('player.leftRealm', { player: this.player });
  }

  hungup() {
    eventBus.emit('player.leftRealm', { player: this.player });
  }
}

module.exports = Game;
